-- Nave presente en el detalle operativo (hoja "BD") que no aparece en el
-- resumen comparativo de puertos.
insert into naves (nombre, puerto_id, producto_id)
select 'AFRICAN ROADRUNNER',
       (select id from puertos where nombre = 'Chancay'),
       (select id from productos where nombre = 'Maíz amarillo argentino')
where not exists (select 1 from naves where nombre = 'AFRICAN ROADRUNNER');
